export const transactionRecoveryContract={inspect:'project.recovery.inspect',resolve:'project.recovery.resolve',open:'project.recovery.open',fields:'transaction, expectedRevision, choices: {exact project path: before|after|disk}, dryRun?:bool',read:'No transaction: compact pending IDs/counts. Transaction: offset/limit (default32 max128), exact byte hashes/existence/size, no binary payload. Revision covers entire journal and all current disk bytes.',rename:'rename:UUID file/model-sidecar location and metadata journal; streamed hashes/inode, no content backup. before restores verified original group; all rows require explicit choices; after moves a remaining sole source to its new name with current bytes; disk preserves current bytes/deletion and reconciles unique asset IDs. Both locations present require separate external preservation first. Directory/private-folder rename remains legacy.',writeIntent:'write:UUID identity-only intents offer disk preservation only; content bytes never rewritten and current asset ID preserved. No fabricated old payload.',decision:'Conflicting files require explicit choices. Other rows default to before. Disk preserves current bytes/deletion. No image/text reinterpretation or three-way binary merge.',safety:'Ordinary project writes blocked while any prepared conflict remains. Read/inspection available. Entire group checked before writes and after publication; revision change rejects without writes. Resolution itself has a linked write-ahead child journal.',restart:'Committed child completes parent resolution. Prepared child rolls back to the third-party disk baseline; original unresolved decision remains. Records retained for recovery, not duplicated engine/install backups.',limits:['No hardware power-loss durability guarantee','No multi-process filesystem lock; external races produce retained conflict records','Changed disk baselines limited to16MiB per file and32MiB resolution journal; choosing disk requires no backup copy','Ordinary document Undo is separate from this disk group recovery']};

// Uses the existing asset dialog. Hash/size rows remain paged and no binary
// payload is copied into the DOM, browser storage or an automation reply.
export function renderTransactionRecovery(element,{inspect,resolve,changed=()=>{}}){
 const document=element.ownerDocument;let closed=false,serial=0,state=null,selected='',offset=0,choices={},revision='',pending=[];const pageSize=32;
 const title=document.createElement('h2'),status=document.createElement('p'),selector=document.createElement('select'),rows=document.createElement('div'),footer=document.createElement('footer'),previous=document.createElement('button'),next=document.createElement('button'),refresh=document.createElement('button'),preview=document.createElement('button'),apply=document.createElement('button');
 title.textContent='저장 묶음 복구';status.setAttribute('role','status');selector.setAttribute('aria-label','복구할 저장 묶음');rows.className='transaction-recovery-rows';for(const[b,text]of [[previous,'이전'],[next,'다음'],[refresh,'다시 읽기'],[preview,'미리보기'],[apply,'선택 적용']]){b.type='button';b.textContent=text;footer.append(b);}element.replaceChildren(title,status,selector,rows,footer);
 const busy=value=>{for(const b of [selector,previous,next,refresh,preview,apply])b.disabled=value;for(const field of rows.querySelectorAll('select'))if(field.tagName==='SELECT')field.disabled=value;};
 const sayError=e=>status.textContent='복구하지 못했어요: '+e.message;
 function draw(){rows.replaceChildren();if(!state){previous.disabled=next.disabled=apply.disabled=preview.disabled=true;return;}previous.disabled=offset===0;next.disabled=offset+state.rows.length>=state.total;status.textContent=(state.kind==='rename'?'파일 이름 변경 · ':'')+state.total+'개 파일 · 외부 충돌 '+state.conflicts+'개';
  for(const row of state.rows){const item=document.createElement('section'),label=document.createElement('label'),select=document.createElement('select'),info=document.createElement('div');label.textContent=row.target?row.path+' → '+row.target:row.path;select.setAttribute('aria-label',row.path+' 복구 선택');
   for(const[value,text]of [['',state.kind==='rename'||row.conflict?'선택하세요':'저장 전 (기본)'],['before',state.kind==='rename'?'묶음 원래 이름 복구':'저장 전'],['after',state.kind==='rename'?'현재 내용으로 새 이름 정리':'저장 시도'],['disk','현재 디스크 보존']].filter(([value])=>!value||!row.availableChoices||row.availableChoices.includes(value))){const option=document.createElement('option');option.value=value;option.textContent=text;select.append(option);}select.value=choices[row.path]||'';select.onchange=()=>{if(select.value)choices[row.path]=select.value;else delete choices[row.path];};label.append(select);
   for(const[key,text]of [['before','저장 전'],['after','저장 시도'],['disk','디스크']]){const value=row[key],line=document.createElement('p');line.textContent=text+': '+(value.exists?(value.bytes===null?'크기 기록 없음':value.bytes+' B')+' · '+value.hash:'파일 없음');info.append(line);}if(row.recordedAssetId){const id=document.createElement('p');id.textContent='현재 에셋 ID: '+(row.currentAssetId||'없음')+' · 저장 기록 ID: '+row.recordedAssetId;info.append(id);}if(row.target)for(const [key,text]of[['source','원래 위치 현재 파일'],['targetFile','새 위치 현재 파일']]){const value=row[key],line=document.createElement('p');line.textContent=text+': '+(value.hash?value.bytes+' B · '+value.hash:'파일 없음');info.append(line);}item.append(label,info);rows.append(item);
  }
 }
 async function load({list=false}={}){if(closed)return;const ticket=++serial;busy(true);try{if(list){const result=await inspect({});if(closed||ticket!==serial)return;pending=result.pending;selector.replaceChildren();for(const row of pending){const option=document.createElement('option');option.value=row.id;option.textContent=(row.label||row.id)+(row.blockedBy?' · 하위 복구 대기':'');option.disabled=!!row.blockedBy;selector.append(option);}if(!pending.some(r=>r.id===selected&&!r.blockedBy)){selected=pending.find(r=>!r.blockedBy)?.id||'';choices={};revision='';offset=0;}selector.value=selected;}
   if(!selected){state=null;rows.replaceChildren();status.textContent='복구할 저장 묶음이 없어요.';return;}const result=await inspect({transaction:selected,offset,limit:pageSize});if(closed||ticket!==serial)return;if(revision&&revision!==result.revision){choices={};status.textContent='파일이 바뀌어 선택을 초기화했어요.';}revision=result.revision;state=result;draw();
  }catch(e){if(!closed&&ticket===serial)sayError(e);}finally{if(!closed&&ticket===serial){busy(false);if(!state){previous.disabled=next.disabled=apply.disabled=preview.disabled=true;}else{previous.disabled=offset===0;next.disabled=offset+state.rows.length>=state.total;apply.disabled=preview.disabled=!!state.blockedBy;}}}}
 selector.onchange=()=>{selected=selector.value;choices={};revision='';offset=0;state=null;return load();};previous.onclick=()=>{offset=Math.max(0,offset-pageSize);return load();};next.onclick=()=>{offset+=pageSize;return load();};refresh.onclick=()=>load({list:true});
 const submit=async dryRun=>{if(closed||!state)return;busy(true);try{const result=await resolve({transaction:selected,expectedRevision:revision,choices:{...choices},dryRun});if(closed)return;if(dryRun){status.textContent=result.valid?'선택 내용을 적용할 수 있어요.':'선택하지 않은 충돌 '+result.unresolvedCount+'개';return;}await changed(result);if(!closed){choices={};revision='';state=null;await load({list:true});}}catch(e){if(!closed)sayError(e);}finally{if(!closed){busy(false);previous.disabled=!state||offset===0;next.disabled=!state||offset+state.rows.length>=state.total;apply.disabled=preview.disabled=!state||!!state.blockedBy;}}};
 preview.onclick=()=>submit(true);apply.onclick=()=>submit(false);const ready=load({list:true});return{ready,refresh:()=>load({list:true}),dispose(){closed=true;serial++;choices={};state=null;pending=[];}};
}
